import numpy as np
def solve_radiation(L, n, T_left, T_right, epsilon):
    dx = L/(n-1)
    A = np.zeros((n, n)); b = np.zeros(n)
    A[0,0] = 1.0; b[0] = T_left
    A[-1,-1] = 1.0; b[-1] = T_right
    for i in range(1, n-1):
        A[i, i-1] = 1.0; A[i, i] = -2.0; A[i, i+1] = 1.0
        b[i] = (T_right - T_left) / (epsilon * dx)
    return list(np.linalg.solve(A, b))

